#Requires -Version 7
<#
dashboard.tests.ps1: the supervise page's history graphs (adapters/supervise-stats.ps1): lease waits per resource from the logs,
test-run results per day, CPU per lane process and top other processes; their cards; tile rows of one height (ui-check).
Usage: pwsh -NoProfile -File <kit>/tests/dashboard.tests.ps1 (or tests/kit-tests.ps1 -Area dashboard).
Exit codes: 0 pass · 1 a check failed.
#>
. (Join-Path $PSScriptRoot 'harness.ps1')
$k = New-TestKit dashboard; $O = Join-Path $k 'skills/bossy/bossy.ps1'
# lease waits: a tab acquire logged since = wait start, a gate start waitSec, a train's lease-wait; a lock with no wait and short waits drop; noon: one clock hour
$lwr = & { . $O; $n = (Get-Date).Date.AddHours(12); $t = $n.AddMinutes(-30); $iso = { param($m) $t.AddMinutes($m).ToString('o') }; $dd = Join-Path (Get-KitPath audit -Create) $n.ToString('yyyy-MM-dd'); New-Item -ItemType Directory -Force $dd | Out-Null
  @(@{ at = (& $iso 0); event = 'acquire'; kind = 'tab'; name = 'k1'; agent = 'c1'; since = (& $iso -10) }, @{ at = (& $iso 0); event = 'acquire'; kind = 'lock'; name = 'L'; agent = 'c2'; since = (& $iso 0) }, @{ at = (& $iso 0); event = 'release'; kind = 'tab'; name = 'k1'; since = (& $iso -20) }) | ForEach-Object { $_ | ConvertTo-Json -Compress } | Set-Content (Get-KitLogFile leases -Create)
  @(@{ at = (& $iso 0); event = 'start'; owner = 'd1'; waitSec = 600 }, @{ at = (& $iso 0); event = 'start'; owner = 'd2'; waitSec = 5 }) | ForEach-Object { $_ | ConvertTo-Json -Compress } | Set-Content (Join-Path $dd 'builds.jsonl')
  @{ at = (& $iso 0); event = 'lease-wait'; env = 'rm2'; services = @('api', 'web'); holders = @('H'); min = 4 } | ConvertTo-Json -Compress | Set-Content (Join-Path $dd 'env.jsonl')
  $w = Get-KitLeaseWaits $n; $hc = @($w.rows | Where-Object name -eq 'browser seats')[0].hours | Where-Object { $_[0] }
  "$(@($w.rows | ForEach-Object { "$($_.name)=$($_.n)/$([math]::Round($_.min))" } | Sort-Object) -join ',')|$($hc[3])"
  $html = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ waits = $w } }); "$($html -match "Waits min")|$($html -match "title='[^']*&#183; 1 waits &#183; 10 min &#183; longest 10 min &#183; c1'")" }
Expect "lease waits: wait = acquire since..at per resource (tab = browser seats, gate waitSec, a train per service), under 30 s none; card + cell tooltip ($lwr)" ($lwr -join ' ' -eq 'browser seats=1/10,build gate=1/10,rm2 · api=1/4,rm2 · web=1/4|c1 True|True')
# test runs: results.json by write day; PASS_WITH_NOTE = PASS, PENDING none, a cause outside the list = other; an old run is out
$qa = & { . $O; $r = Get-KitPath qa-runs -Create; $f = Join-Path (New-Item -ItemType Directory -Force (Join-Path $r 'run1/T1')) 'results.json'; $f2 = Join-Path (New-Item -ItemType Directory -Force (Join-Path $r 'old/T1')) 'results.json'
  $cs = @(@{ result = 'PASS' }, @{ result = 'PASS_WITH_NOTE' }, @{ result = 'FAIL' }, @{ result = 'NOT_TESTED'; cause = 'env-data' }, @{ result = 'NOT_TESTED' }, @{ result = 'OUT_OF_SCOPE' }, @{ result = 'PENDING' })
  foreach ($x in $f, $f2) { @{ checks = $cs } | ConvertTo-Json -Depth 4 | Set-Content $x }; (Get-Item $f2).LastWriteTime = (Get-Date).AddDays(-9)
  $q = Get-KitQaDays; $d = $q.days[-1]; "$(@($q.days).Count) $($d.pass)/$($d.fail)/$($d.nt)/$($d.oos) $(@($d.runs).run) $($q.causes.'env-data')+$($q.causes.other) $(@($q.days | ForEach-Object { @($_.runs).Count }) -join '')"
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = (Get-Date).ToString('o'); stats = [pscustomobject]@{ qa = $q } }); $gq = "data-g='dg-qa'"; $qt = $h.Substring([math]::Max(0, $h.IndexOf($gq))) -replace "data-g='dg-(?!qa)[\s\S]*"
  "$($h.Contains('id=sec-qa') -or $h.Contains('Test runs, 7 days')) $($h.IndexOf('id=sec-trends') -lt $h.IndexOf($gq) -and $h.IndexOf($gq) -lt $h.IndexOf('id=sec-tuning')) $($qt -match "^data-g='dg-qa'><div class='gk rgh dgh'><button type=button class=rgb aria-expanded=true><span class=gn0>Test checks</span><span class=gcn>6</span><span class=fsm>40% pass &#183; not tested: (env-data 1 &#183; other 1|other 1 &#183; env-data 1)</span>") $([regex]::Matches($qt, "data-mk='qa-").Count) $($qt -match "(?s)data-mk='qa-pass-day'.*?<span class='gc'>2</span>") $($e = { param($x) [Net.WebUtility]::HtmlEncode("$x") }; (Get-KitQaDayRows ([pscustomobject]@{ days = @([pscustomobject]@{ day = (Get-Date).ToString('yyyy-MM-dd'); pass = 0; fail = 0; nt = 0; oos = 3 }) }))[0].ex -eq '— pass')" }
Expect "test checks (owner 2026-11-24: a Per day row group, no tile): 7 days, today 2 PASS / 1 FAIL / 2 NOT_TESTED / 1 OUT_OF_SCOPE, causes env-data + other, old run out; header: checks, pass % without OUT_OF_SCOPE, causes; a row per result, its 7-day sum; OUT_OF_SCOPE only: no pass % ($qa)" ($qa -join ' ' -eq '7 2/1/2/1 run1 1+1 0000001 False True True 4 True True')
# CPU: % of the machine from CPU seconds between two snapshots; a hook group = its process tree; others 10%+ with the shell's owner
$cpu = & { . $O; $c = [math]::Max(1, [Environment]::ProcessorCount); $n = Get-Date
  function Get-KitSweepProcs { foreach ($p in @(@(100, 1, 60), @(101, 100, 30), @(200, 250, 540), @(250, 1, 0), @(300, 1, 6), @(0, 0, 300))) { [pscustomobject]@{ Id = $p[0]; ParentId = $p[1]; Name = "p$($p[0]).exe"; Cpu = 1000 + $p[2] * $c } } }
  function Get-KitCpuGroupsT { @{ name = 'e · api'; pid = 100 } }
  $acc = [pscustomobject]@{ '100|' = 1000; '101|' = 1000; '200|' = 1000; '250|' = 1000; '300|' = 1000; idle = 1000 }
  $s = (Update-KitCpuStats ([pscustomobject]@{ at = $n.AddSeconds(-600).ToString('o'); acc = $acc; samples = @() }) $n @(@{ pid = 250; owner = 'devy-1' }) @(@{ name = 'browser x'; pid = 300 })).samples[-1]
  "$($s.g.'e · api') $($s.all) $(@($s.top | ForEach-Object { "$($_.n):$($_.p):$($_.o)" }) -join ',') $($s.g.'browser x')/$($s.m.Contains('browser x'))"
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ cpu = @{ samples = @($s, $s) } } }); "$($h -match "class='cpo f hot'") $($h -match "<span class=gn title='e &#183; api: CPU now 15% &#183; 24 h peak 15% &#183; avg 15% &#183; RAM now [\d.]+ GB[^']*'>e &#183; api</span>" -and $h -match "\(now\) &#183; e &#183; api &#183; CPU avg 15% &#183; peak 15% &#183; RAM [\d.]+ GB'") $($h -match "\(now\) &#183; whole machine &#183; CPU avg 50% &#183; peak 50% &#183; RAM — &#183; top: p200.exe 90%'" -and $h -match "class='gks w5 cpg rsh'" -and $h -match "id=sec-res24 open><summary><h4>Resources &#183; 24 h</h4>")" }
Expect "cpu: group = its tree (15%), machine from idle time (50%), top other 90% with its shell's owner; Resources · 24 h: red row, a row per lane service (CPU avg / peak + its tree's RAM in the cell), the machine row's cells name the hour's top processes ($cpu)" ($cpu -join ' ' -eq '15 50 p200.exe:90:devy-1 1/True True True True')
# Kit health · 7 days (UI-C, one day heatmap): the day's average sweep, compact (229037567 -> 229M), a day without samples blank,
# agents failed / finished from the day records; no tile, sparkline, day bars or flag rows (Flags · 24 h has them)
$spk = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $lv = @(@{ at = $n.AddDays(-2).ToString('o'); secs = 229037567; fl = 4; fx = 1; br = 9; wt = 3 }, @{ at = $n.AddMinutes(-20).ToString('o'); secs = 20; fl = 2; fx = 0; br = 7; wt = 2 }, @{ at = $n.AddMinutes(-10).ToString('o'); secs = 40 })
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); history = @(@{ at = $n.AddMinutes(-5).ToString('o'); flags = @(@{ level = 'ACT' }, @{ level = 'WATCH' }, @{ level = 'WATCH' }, @{ level = 'WATCH' }); fixed = 2 })
      stats = [pscustomobject]@{ live = $lv; now = [pscustomobject]@{ secs = 40; slow = 'wave reports 9 s'; disks = @() }; days = @(@{ day = $n.AddDays(-1).ToString('yyyy-MM-dd'); failed = 2; left = 5 }) } }); $h }
$spkRow = { param([string]$nm) $m = [regex]::Match($spk, "(?i)<span class=gn[^>]*>$nm(<small>[^<]*</small>)?</span><span class='gs hm dy[^']*' style='--n:7'[^>]*>(.*?)</span><span class='gc[^']*'>([^<]*)</span>"); if ($m.Success) { "$(@([regex]::Matches($m.Groups[2].Value, '>([^<]*)</i>') | ForEach-Object { $_.Groups[1].Value }) -join ',')=$($m.Groups[3].Value)" } else { 'none' } }
$spkGot = @('Sweep time \(s\)', 'agents failed', 'agents finished', 'all branches', 'all worktrees' | ForEach-Object { & $spkRow $_ }) -join ' | '
Expect "Kit health · 7 days: a day heatmap row per series, compact values, empty days blank, totals right; no Activity tiles left ($spkGot)" ($spkGot -eq ',,,,229M,,30=114.5M | ,,,,,2,=2 | ,,,,,5,=5 | ,,,,9,,7=9 | ,,,,3,,2=3' -and $spk -notmatch '229037567|Workflow steps now|Sweep time</div>|Agents failed</div>|Flags auto-FIXED|branches and worktrees, |flags per sweep|auto-fixed per sweep' -and $spk -match 'id=sec-dl-days open>')
# every fact once (owner 2026-11-19): each widget names its metric (data-mk); a key twice on one page = two widgets with the same numbers
$mkp = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $d0 = $n.ToString('yyyy-MM-dd')
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); history = @(@{ at = $n.ToString('o'); flags = @(@{ level = 'ACT' }); fixed = 1 })
      stats = [pscustomobject]@{ live = @(@{ at = $n.AddMinutes(-9).ToString('o'); secs = 30; br = 4; wt = 2; disks = @{ 'C:' = 50 } }); now = [pscustomobject]@{ secs = 30; disks = @(@{ drive = 'C:'; free = 50; rate = 0.1 }) }; days = @(@{ day = $d0; failed = 1; left = 3 })
        repos = @{ at = $n.ToString('o'); repos = @(@{ repo = 'api'; branches = 3; worktrees = 1 }) }; flagHours = @(@{ h = $n.ToString('yyyyMMddHH'); f = @(@{ l = 'ACT'; k = 'STUCK'; y = 'a'; t = 'STUCK a' }) })
        usage = [pscustomobject]@{ days = @(@{ day = $d0; tok = 5000; cost = 2 }); rates = @{ n = 3; empty = 1; fail = 0; stopped = 0; running = 0; stuck = 0 }; byRole = @(@{ k = 'devy'; n = 3; sum = 5000; cost = 2; avgMin = 1; p90Min = 2; models = @(); types = @(@{ k = 'build'; n = 2; avg = 2000; p50 = 2000; p90 = 2500; avgMin = 1; p90Min = 2 }, @{ k = 'fix'; n = 1; avg = 1000; p50 = 1000; p90 = 1000; avgMin = 1; p90Min = 1 }) }) } } })
  $ks = @([regex]::Matches($h, "data-mk='?([^ '>]+)") | ForEach-Object { $_.Groups[1].Value }); $dup = @($ks | Group-Object | Where-Object Count -gt 1 | ForEach-Object Name)
  $want = @('sweep-day', 'agents-failed-day', 'branches-day', 'repo-day-api', 'flags-hour', 'res-hour', 'cost-day', 'tokens-day', 'review-share', 'spend-role', 'trend-tiles') | Where-Object { $_ -notin $ks }
  $e = { param($x) [Net.WebUtility]::HtmlEncode("$x") }; $two = Format-KitDayHeat @(@{ n = 'a'; mk = 'x-day'; v = @(1) }, @{ n = 'b'; mk = 'x-day'; v = @(2) }) @($d0) 'k'; $dup2 = @([regex]::Matches($two, "data-mk='?([^ '>]+)") | ForEach-Object { $_.Groups[1].Value } | Group-Object | Where-Object Count -gt 1).Count
  "dup:$($dup -join ',') missing:$($want -join ',') seen2:$dup2 spend:$([regex]::Matches($h, "<span class=gn title='devy: build 2 steps, avg 2k &#183; fix 1 steps, avg 1k'>devy</span>").Count)" }
Expect "metric keys: each once on the page (the expected ones present), a key twice is caught; spend: a role row of the heatmap, its step types in the tooltip ($mkp)" ($mkp -eq 'dup: missing: seen2:1 spend:1')
# resources (owner 2026-11-19): one view; the held table is gone; a holder text parses grace after a branch, parked, a wait note kept whole
$hpt = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); agents = @(); resources = @() })
  $p = @((Split-KitHolder 'devy-1 (fix/x) (grace 5 min)'), (Split-KitHolder 'parked: fix/y'), (Split-KitHolder 'devy-2 (waiting for RAM)'), (Split-KitHolder ''))
  "$($h -notmatch 'Resources and leases|class=hlt' -and $h.Contains('.cpg .gk.hot>.gc:nth-last-child(15)')) $(@($p | ForEach-Object { "$($_.h)/$($_.b)/$($_.g)" }) -join '|')" }
Expect "resources: no held table; holder parts ($hpt)" ($hpt -eq 'True devy-1/fix/x/ (grace 5 min)|parked/fix/y/|devy-2 (waiting for RAM)//|//')
# Repos (owner 2026-11-24): a Per day group, a row per repo
$syh = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $lv = @(@{ at = $n.AddDays(-1).ToString('o'); br = 2; wt = 1; rp = @{ api = @(2, 1) } })
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ live = $lv; repos = @{ at = $n.ToString('o'); repos = @(@{ repo = 'api'; branches = 3; worktrees = 1; kept = 2 }) }
        sync = @(@{ repo = 'api'; diverged = @('lane-ish [ahead 1, behind 2]') }) } }); $h }
Expect 'repos group: totals + as of, a repo row (2/1 from a sample, today 3/1 red, its diverged branch), kept + diverged on its line' ($syh -match "<span class=gn0>Repos</span><span class=gcn>1</span><span class=fsm>3 branches &#183; 1 worktrees &#183; 2 kept &#183; 1 diverged &#183; as of 10:00</span>" -and $syh -match "(?s)data-mk='repo-day-api'><span class=gn[^>]*>api<small>kept 2 (·|&#183;) <span class=rdv>diverged 1</span></small></span>.*?>2/1</i><i data-t=act class='nw[^']*' style='--a:100%' title='2026-01-02 \(today\) &#183; api: 3 branches &#183; 1 worktrees &#183; kept 2 [^']*\ndiverged: lane-ish \[ahead 1, behind 2\]'>3/1</i>" -and $syh -notmatch 'sec-repos-now')
# flags heatmap: distinct flags per clock hour (a flag seen twice in one hour counts once), auto-fixed = FIXED, 24 h kept; ACT row + a kind sub-row, the count in the cell
$drwHold = "if(d.querySelector('dialog.drw[open]')){sa();return}"
$fhm = & { . $O; $n = [datetime]'2026-01-02T10:20:00'; $fa = @{ level = 'ACT'; what = 'STUCK W1 (r1): no progress' }
  $fh = Update-KitFlagHours @(@{ h = '2025123109'; f = @(@{ l = 'ACT'; k = 'OLD'; y = 'old'; t = 'old' }) }) $n.AddHours(-1) @($fa, @{ level = 'INFO'; what = 'auto-fixed: killed shell 7' }, @{ level = 'INFO'; what = 'plain' })
  $fh = Update-KitFlagHours $fh $n @($fa, @{ level = 'WATCH'; what = 'disk D: low' }); $fh = Update-KitFlagHours $fh $n.AddMinutes(10) @($fa)
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.AddMinutes(10).ToString('o'); stats = [pscustomobject]@{ flagHours = $fh } })
  "$(@($fh.h) -join ',') $(@($fh | ForEach-Object { @($_.f).Count }) -join ',') $(@($fh[0].f.l) -join '/') $($h -match "<div class='gk l-act gl0'><span class=gn[^>]*>ACT</span><span class='gs hm fh l-act'[^>]*>(<i[^>]*></i>){22}<i class=hi style='--a:100%' title='09:00 &#183; 1 ACT: STUCK W1 \(r1\): no progress'>1</i><i class='nw hi' style='--a:100%'[^>]*>1</i></span><span class='gc'>1</span>") $($h -match "<div class='gk l-act fk'><span class=gn[^>]*>STUCK</span>") $($h -match 'id=sec-flagmap open>') $($h.Contains($drwHold))" }
Expect "flags heatmap: per hour distinct, FIXED from auto-fixed, old hour dropped; level row + kind row, count in the cell, folded open while busy; auto-refresh waits while the drawer is open ($fhm)" ($fhm -eq '2026010209,2026010210 2,2 ACT/FIXED True True True True')
# flag kinds are data: each leading CAPS phrase is its own row (UNTRACKED MR, PRIOR OVERRIDE); old stored 'other' re-read; 'other' only without a kind word
$fkr = & { . $O; $n = [datetime]'2026-01-02T10:20:00'; $fh = @(@{ h = '2026010210'; f = @(@{ l = 'WATCH'; k = 'other'; y = 'a'; t = 'UNTRACKED MR !5 open' }, @{ l = 'WATCH'; k = 'other'; y = 'b'; t = 'PRIOR OVERRIDE x' }, @{ l = 'WATCH'; k = 'other'; y = 'c'; t = 'disk D: low' }, @{ l = 'WATCH'; k = 'other'; y = 'd'; t = 'LANE RM 2 busy' }) })
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ flagHours = $fh } }); "$($h -match '<span class=gn[^>]*>UNTRACKED MR</span>') $($h -match '<span class=gn[^>]*>PRIOR OVERRIDE</span>') $($h -match '<span class=gn[^>]*>other</span>') $($h -match '<span class=gn[^>]*>LANE</span>' -and $h -notmatch '>LANE RM<')" }
Expect "flags heatmap: a row per kind phrase, stored 'other' re-read, no kind word stays other ($fkr)" ($fkr -eq 'True True True True')
# Branch / task on the Resources · 24 h row: a QA code and pid of a board agent resolve to a task / item; the holder in its own small, escaped
$btk = & { . $O; $qd = Join-Path (Get-KitPath qa-runs -Create) 'run1'; New-Item -ItemType Directory -Force $qd | Out-Null
  @{ run = 'run1'; items = @{ T5 = @{ tasks = @('t1'); pubKey = 'pk9' } } } | ConvertTo-Json -Depth 5 | Set-Content (Join-Path $qd 'index.json')
  $bd = Get-KitPath board -Create; @{ agent = 'devy-7'; run = 'r7'; items = 'CODE1'; status = 'active'; pid = 4242 } | ConvertTo-Json | Set-Content (Join-Path $bd 'devy-7-aa.json')
  $n = [datetime]'2026-01-02T10:00:00'; $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); resources = @([pscustomobject]@{ name = 'browser rm·x'; by = 'test:T5'; gb = 1 }, [pscustomobject]@{ name = 'phone P1'; by = 'pid-4242'; gb = 1 },
      [pscustomobject]@{ name = 'slot a·Kite'; by = "devy-1 (fix/x) (grace 5 min)"; gb = 0 }, [pscustomobject]@{ name = 'phone P2'; by = ''; gb = 0 }, [pscustomobject]@{ name = 'mysql (rm, hm)'; kind = 'env'; shared = $true; gb = 1 }) })
  "$($h -match '>browser rm&#183;x<small>test:T5</small><small class=bt>QA T5 &#183; pk9</small>') $($h -match '>phone P1<small>pid-4242</small><small class=bt>CODE1</small>') $($h -match '>slot a&#183;Kite<small>devy-1 \(grace 5 min\)</small><small class=bt>fix/x</small>') $($h -match '>phone P2<small>no live holder</small></span>') $($h -match '>mysql \(rm, hm\)<small>shared &#183; always on</small></span>')" }
Expect "resources: holder + branch / task on each Resources · 24 h row, a dash-free blank, shared kept ($btk)" ($btk -eq 'True True True True True')
# gate rows (K28): every kind of the 24 h log its own row (presets only label), rows idle 12 h folded (K22); Resources · 24 h (K25/K27): a
# configured stopped service keeps a (folded) row, RAM from a lease first, else its process tree; the idle fold names its count
$gtr = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $hr = { param($b) , @(0..23 | ForEach-Object { if ($_ -eq $b) { , @(1, 30, 0) } else { , @(0, 0, 0) } }) }
  $gs = [pscustomobject]@{ h0 = $n.AddHours(-23).ToString('o'); rows = @([pscustomobject]@{ name = 'zig-build'; hours = (& $hr 22) }, [pscustomobject]@{ name = 'maven test'; hours = (& $hr 2) }) }
  $cpu = [pscustomobject]@{ svc = @('e · api', 'e · web'); samples = @([pscustomobject]@{ at = $n.AddMinutes(-30).ToString('o'); s = 600; all = 20; g = @{ 'e · api' = 5 }; m = @{ 'e · api' = 1.5 }; top = @() }) }
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); mem = @{ TotalGB = 16; AvailGB = 8 }; stats = [pscustomobject]@{ gate = $gs; cpu = $cpu } })
  "$($h -match '>zig-build</span>' -and (Get-KitGateGroup 'zig-build' 'x') -eq 'zig-build') $($h -match "<div class='gk mb'><span class=gn[^>]*>maven test<") $($h -match "<div class='rgg cl' data-g='rg-env'>.*?<span class=gn title='e &#183; web: CPU not sampled") $($h -match "title='09:00 &#183; e &#183; api &#183; CPU avg 5% &#183; peak 5% &#183; RAM 1.5 GB'") $($h -match "id=sec-res24 open><summary><h4>Resources &#183; 24 h</h4><span class=cnt>\(4 of 5 busy\)")" }
Expect "gate kinds from the log (unknown = own row), idle rows folded; Resources · 24 h: a stopped configured service keeps its row in a folded group, RAM from its tree ($gtr)" ($gtr -eq 'True True True True True')
# Delivery (K23, K29, UI-C): one day heatmap: MRs merged per repo (config repos + any with an MR; none: folded; lead time p50 in the tooltip), tasks closed (a click filters), work in flight by status (tap = its tasks)
$dlv = & { Set-JsonFile (Join-Path $k 'skills/crafty/kit.local.json') @{ repos = @(@{ name = 'alpha' }, @{ name = 'quiet' }) }; . $O; $n = Get-Date; $d0 = $n.ToString('yyyy-MM-dd'); $d1 = $n.AddDays(-1).ToString('yyyy-MM-dd')
  $up = [pscustomobject]@{ days = @([pscustomobject]@{ day = $d1; merged = 1 }, [pscustomobject]@{ day = $d0; merged = 2 }); dayRuns = @{}; tpm = ''; mrs = @(@{ ref = 'alpha!1'; day = $d1; lead = 10 }, @{ ref = 'alpha!2'; day = $d0; lead = 4 }, @{ ref = 'beta!7'; day = $d0; lead = 6 }) }
  $outS = [pscustomobject]@{ kpi = [pscustomobject]@{}; weekly = @(); repos = @(); tasks = @([pscustomobject]@{ id = 'T-1'; repos = @(); bucket = 'wait'; stage = 'review' }, [pscustomobject]@{ id = 'T-2'; repos = @(); bucket = 'wait'; stage = 'untested' }, [pscustomobject]@{ id = 'T-3'; repos = @(); bucket = 'r0'; stage = 'passed'; closedAt = $n.ToString('o') }); stageDays = @{ $d1 = @([pscustomobject]@{ id = 'T-1'; stage = 'open' }, [pscustomobject]@{ id = 'T-9'; stage = 'review' }) } }
  $e = { param($x) [Net.WebUtility]::HtmlEncode("$x") }; $n1 = { param($v) ([double]$v).ToString('0.#', [cultureinfo]::InvariantCulture) }; $grid = { param($c, $m, $i) "$($i -join '')" }; $spark = { '' }; $taskA = { param($t) "<a>$t</a>" }
  $fold = { param([string]$id, [string]$title, $count, [string]$inner, [switch]$Open, [string]$tag = 'h3', [string]$cls = '') "<details id=sec-$id$(if ($Open) { ' open' })><summary>$title ($count)</summary>$inner</details>" }
  $h = Format-KitDeliveryHtml $outS $up
  "$($h -match "<span class=gn[^>]*>alpha</span><span class='gs hm dy fh l-mr' style='--n:2'[^>]*><i[^>]*title='$d1 &#183; alpha: 1 MR\(s\) merged: alpha!1 &#183; lead time p50 10 h'>1</i><i class='nw hi'[^>]*>1</i></span><span class='gc'>2</span>") $($h -match '>beta</span>' -and $h -match "5 idle rows · no data in 2 days</button><div class=gki><div class=gk data-mk='mrs-day-quiet'><span class=gn[^>]*>quiet<") $($h -match "data-fv='st:review'[^>]*>1</i>" -and $h -match "data-fv='st:intest'" -and $h -match "<li data-fk='st:review'>" -and $h -match "tasks closed</span><span [^>]*><i[^>]*></i><i tabindex=0 role=button data-ft='#oc-tasks' data-fv='dc$d0'[^>]*>1</i>" -and $h -match "<li data-fk='dc$d0'>" -and $h -notmatch "data-fk='[^']*st:passed") $($h -match 'id=sec-dl-days open><summary>Per day \(3 MRs · lead time p50 6 h\)' -and $h -notmatch 'sec-dl-lead|sec-dl-repoday') $($h -match "<span class=gn0>Delivery</span><span class=fsm>3 MRs merged \(alpha 2 &#183; beta 1\) &#183; 1 tasks closed &#183; 0 came back</span>" -and $h -match "<span class=gn0>Tasks by outcome</span><span class=gcn>3</span><span class=fsm>passed 1 &#183; came back 0 &#183; not tested yet 2</span>" -and $h -notmatch "Work in flight|dg-flight|sec-dl-repos|sec-dl-flight|class='ug dlv'|class=obr")"
  # status history (owner 2026-11-25): yesterday from stageDays (T-1 in progress, T-9 in review; tooltip only), today = now; no stageDays: today-only rows fold into the group line
  $dlvH = "$($h -match "title='$d1 &#183; review: 1 task\(s\) at the day&#39;s end: T-9'>1</i>" -and $h -match "title='$d1 &#183; in progress: 1 task\(s\) at the day&#39;s end: T-1'>1</i>" -and $h -notmatch "data-fv=''")"
  $outS.stageDays = @{}; $h2 = Format-KitDeliveryHtml $outS $up
  "$dlvH $($h2 -match "0 came back (·|&#183;) now: review 1 &#183; in test 1</span>" -and $h2 -notmatch "data-mk='flight-")" }
Expect "Per day: Delivery group (repo x day map from config + MRs, idle repo folded, a tasks-closed day filters the list, status rows: a past day from stageDays, today's cell filters), group lines summarise each group, no Work in flight group; today-only rows fold into the group line ($dlv)" (($dlv -join ' ') -eq 'True True True True True True True')
# runs timeline (D9, owner 2026-11-19): a row per run (a usage run; board agents outside one by their run), agents under it, the hour cells
# = active minutes; one agent = one row: B1's board row under the QA run that wf_a runs (its launch record's runDir) joins wf_a
$agg = & { . $O; @{ run = 'wf_a'; runDir = (Join-Path (Get-KitPath qa-runs) 'qa-run-1') } | ConvertTo-Json | Set-Content (Join-Path (Get-KitPath launches -Create) 'self-buildy-wf_a-1a2b.json')
  $n = (Get-Date).Date.AddHours(12); $iso = { param($m) $n.AddMinutes($m).ToString('o') }
  $u = [pscustomobject]@{ days = @(@{ day = $n.ToString('yyyy-MM-dd'); tok = 9 }); runs = @(@{ run = 'old'; id = 'wf_o'; label = 'old run'; kind = 'build'; status = 'ended'; started = (& $iso -600); at = (& $iso -540); tok = 5000; cost = 1.5; wall = 60
      steps = @(@{ label = 'build:A1'; role = 'devy'; at = (& $iso -550); min = 30; result = 'pass'; tok = 4000 }) }) }
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ usage = $u }; agents = @([pscustomobject]@{ name = 'B1 (devy)'; run = 'qa-run-1'; state = 'STUCK'; since = (& $iso -30) },
      [pscustomobject]@{ name = 'B1 (devy)'; run = 'wf_a'; state = 'ACTIVE'; since = (& $iso -90) }, [pscustomobject]@{ name = 'wf_a (workflow)'; run = 'wf_a'; state = 'WAITING' }, [pscustomobject]@{ name = 's (devy)'; run = 'solo'; state = 'ACTIVE'; since = (& $iso -10) }) })
  $memoRows = @((Get-Content (Join-Path (Get-KitPath cache) 'runs-rows.json') -Raw | ConvertFrom-Json -AsHashtable).Keys).Count
  $memoPage = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ usage = $u }; agents = @() })
  $memoSame = (Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ usage = $u }; agents = @() })) -ceq $memoPage
  Write-Host "runs-rows memo: $memoRows row(s) cached, a second render identical: $memoSame"; $script:memoRunsOk = $memoRows -eq 1 -and $memoSame -and $memoPage -match "data-g='rr-wf_o'"
  "$($h -match "data-g='rr-board-wf_a'[^>]*>.*?<span class='chip s-act'>running</span>" -and $script:memoRunsOk -and $h -notmatch "rr-board-qa-run-1" -and ([regex]::Matches($h, '>devy-b1<')).Count -eq 1) $($h -match "(?s)rtg aria-expanded=false>Other</button>.{0,3000}?class=gn title='[^']*'>devy-s<") $($h -match "data-g='rr-wf_o' data-oc='pass' data-fk='d$($n.ToString('yyyy-MM-dd'))'><div class='gk rgh rr f'>" -and $h -match "<span class='gc ks kd-tc k0' title='[^']*'><b>5k \`$1.50</b><small class=knr>split not recorded</small></span><span class='gc ks kd-time k0' title='[^']*'><b>60 min</b><small class=knr>wall clock</small></span>" -and $h -match ">devy-a1</span><span class='gs hm rn'") $($h -match "title='02:00 &#183; old run &#183; 30 min active'>30</i>")" }
Expect "Runs: a row per run, board agents grouped by run (a QA run's row joins its workflow), agents under each, tokens / cost / time, minutes per hour; an ended run's row cached once (runs-rows.json), the page unchanged ($agg)" ($agg -eq 'True True True True')
# no Sessions fold (owner K74): coordinator and agents-outside-workflows sessions show only as their role share in Usage
$ses = & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $sx = @(1..3 | ForEach-Object { @{ session = "c0ffee0$_-aaaa-bbbb"; tok = 1000; cost = 1; min = 5; model = 'claude-x' } })
  $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); stats = [pscustomobject]@{ usage = [pscustomobject]@{ days = @(@{ day = '2026-01-02'; tok = 3000; cost = 3 }); coord = $sx; bg = @(@{ session = 'b1'; n = 1; tok = 9; cost = 0.1; roles = 'x' }) } } })
  "$($h -match 'sec-sessions|Coordinator sessions|by session') $($h -match 'sec-trends')" }
Expect "no Sessions fold: per-session tables gone, Usage stays ($ses)" ($ses -eq 'False True')
# generic (K29): a synthetic config (other repos, no phones, no lanes) + a gate log of one unknown kind: no built-in preset, org or phone row shows
$gen = & { Set-JsonFile (Join-Path $k 'skills/crafty/kit.local.json') @{ repos = @(@{ name = 'svc-x'; checkout = 'D:/nowhere/svc-x' }) }; . $O; $n = Get-Date; $dd = Join-Path (Get-KitPath audit -Create) $n.ToString('yyyy-MM-dd'); New-Item -ItemType Directory -Force $dd | Out-Null
  @{ at = $n.AddMinutes(-5).ToString('o'); event = 'end'; kind = 'zig-build'; owner = 'd1'; project = 'svc-x'; sec = 120; waitSec = 0; code = 0 } | ConvertTo-Json -Compress | Set-Content (Join-Path $dd 'builds.jsonl')
  $g = Get-KitGateStats $n @(); $h = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); mem = @{ TotalGB = 16; AvailGB = 8 }; stats = [pscustomobject]@{ gate = $g; keepFree = 2 } })
  $pre = @($script:KitGateBuiltinLabels | ForEach-Object { $_[0] } | Where-Object { $h -match "class=gn[^>]*>$([regex]::Escape((& { param($x) [Net.WebUtility]::HtmlEncode($x) } $_)))</span>" })
  $otherRx = 'other \('; "$(@($g.rows.name) -join ',')|$($pre -join ',')|$(($h -match 'phone lanes') -ne [bool]$g.lanes)|$($h -match $otherRx)" }   # phone lanes: only when a swarm config has lanes
Expect "generic dashboard: rows from config + data only (an unknown gate kind its own row, no preset / phone / 'other' row) ($gen)" ($gen -eq 'zig-build||False|False')
if (Use-BrowserKit) {   # owner 2026-11-14: one tall tile (25 repos) beside short ones: each column's last tile stretches; without it uiChecks fails
  $uiKb = Join-Path $k 'skills/bossy/kitbag.py'; $pg = Join-Path (Kd) 'tiles.html'; $pg2 = Join-Path (Kd) 'tiles-flat.html'
  & { . $O; $n = [datetime]'2026-01-02T10:00:00'; $lv = @(0..30 | ForEach-Object { [pscustomobject]@{ at = $n.AddMinutes(-20 * $_).ToString('o'); run = $_ % 5; secs = 30 + $_ % 9; br = 30; wt = 9 } }); [array]::Reverse($lv)
    $hT = Format-KitSuperviseHtml ([pscustomobject]@{ at = $n.ToString('o'); history = @(@{ fixed = 1 }, @{ fixed = 0 }); stats = [pscustomobject]@{ live = $lv; now = [pscustomobject]@{ run = 2; done = 3; total = 9; secs = 34; wfr = @(); stale = @(); disks = @() }; repos = @{ at = $n.ToString('o'); repos = @(1..25 | ForEach-Object { @{ repo = "repo-$_-with-a-longer-name"; branches = $_ % 7 + 1; worktrees = $_ % 3 } }) }; days = @(@{ day = '2026-01-01'; failed = 2 }) } })
    # UI-C: the Activity grid keeps one tile (the rest is a day heatmap): 2 short graph tiles (test runs) join it, so the stretch is still exercised
    $e = { param($x) [Net.WebUtility]::HtmlEncode("$x") }; $n1 = { param($x) ([double]$x).ToString('0.#', [cultureinfo]::InvariantCulture) }
    $qtT = "<div class=st data-fit><div class=k>Short</div><figure class=dbr><div class=dbw role=img aria-label='bars'><span class=dbc><b>3</b><i class=qs style='height:40%'></i></span></div></figure></div>"
    $tall = "<div class=st data-fit><div class=k>Tall</div>$(@(1..25 | ForEach-Object { "<div>repo-$_-with-a-longer-name</div>" }) -join '')</div>"; $gA = "<details class='sec sub st uc dlr' id=sec-dl-days open>"; if (-not $hT.Contains($gA)) { throw 'no Per day fold' }
    $hT.Replace($gA, "<div class='cg stats' style='--cmin:220px' data-mas data-fill>$tall$($qtT * 2)</div>$gA") } | Set-Content $pg -Encoding utf8
  (Get-Content $pg -Raw).Replace('if(fill)Object.keys', 'if(0)Object.keys') | Set-Content $pg2 -Encoding utf8
  $u1 = @(& $py -X utf8 $uiKb ui-check $pg --widths 1920,1366 2>&1); $c1 = $LASTEXITCODE; $u2 = @(& $py -X utf8 $uiKb ui-check $pg2 --widths 1366 2>&1)
  Expect "ui-check: Activity tiles stretch to one row height at 1920 + 1366 (exit $c1$(@($u1 -match '^\s+CLIP|render failed') | Select-Object -First 2)); unstretched, uiChecks flags the columns ($(@($u2 -match 'tile columns end|render failed')[0]))" ($c1 -eq 0 -and @($u2 -match 'CLIP cg stats msn: tile columns end \d+ px apart').Count -ge 2)
  # K74: without the 160 px cap the short tiles stretch into an empty band above their graph: uiChecks flags it
  $pg3 = Join-Path (Kd) 'tiles-uncapped.html'; (Get-Content $pg -Raw).Replace('Math.floor(160-lg', 'Math.floor(9999-lg') | Set-Content $pg3 -Encoding utf8
  $u3 = @(& $py -X utf8 $uiKb ui-check $pg3 --widths 1366 2>&1)
  Expect "ui-check: an uncapped stretch leaves an empty band above a graph and is flagged ($(@($u3 -match 'empty above its graph|render failed')[0]))" (@($u3 -match 'a stretched tile: \d+ px empty above its graph').Count -ge 1)
  # owner 2026-11-19: no reserved empty height inside a card (a 60 px band between two blocks is flagged)
  $pg4 = Join-Path (Kd) 'tiles-gap.html'; (Get-Content $pg -Raw).Replace("<details class='sec sub st uc dlr' id=sec-dl-days open>", "<details class='sec sub' id=sec-gap open><summary><h4>Gap</h4></summary><div class=bd><div>a</div><div style='margin-top:60px'>b</div></div></details><details class='sec sub st uc dlr' id=sec-dl-days open>") | Set-Content $pg4 -Encoding utf8
  $u4 = @(& $py -X utf8 $uiKb ui-check $pg4 --widths 1366 2>&1)
  Expect "ui-check: an empty band inside a card is flagged ($(@($u4 -match 'inside a card|render failed')[0]))" (@($u4 -match 'an empty band of \d+ px inside a card').Count -ge 1)
  # owner 2026-11-18: cards 100 / 150 / 250 px: greedy order leaves one column 200 px short; the balancer splits 250 | 250, and uiChecks flags any card grid > 80 px apart
  $bal = "<div class='ug zbal' style='--cmin:300px;--cmax:2' data-mas><div style='height:100px'>a</div><div style='height:150px'>b</div><div style='height:250px'>c</div></div></body>"
  $pg4 = Join-Path (Kd) 'balance.html'; $pg5 = Join-Path (Kd) 'balance-greedy.html'; $h4 = (Get-Content $pg -Raw).Replace('</body>', $bal); Set-Content $pg4 $h4 -Encoding utf8; $h4.Replace('if(ba){', 'if(0){') | Set-Content $pg5 -Encoding utf8
  $u4 = @(& $py -X utf8 $uiKb ui-check $pg4 --widths 1366 2>&1); $u5 = @(& $py -X utf8 $uiKb ui-check $pg5 --widths 1366 2>&1)
  Expect "ui-check: card columns balance (greedy alone is flagged: $(@($u5 -match 'zbal')[0]))" (-not @($u4 -match 'zbal|render failed').Count -and @($u5 -match 'CLIP ug zbal msn: two-column section: columns end \d+ px apart').Count -ge 1)
  $uiLnk = Join-Path (Kd) 'links.html'   # K26: a kit page link navigates away unless it opens in the drawer (data-dw); a web link needs target=_blank
  [IO.File]::WriteAllText($uiLnk, '<p><a href="runs/a.html">bad1</a> <a href="https://x.test/mr/1">bad2</a> <a href="runs/b.html" data-dw="Run b">ok1</a> <a href="https://x.test/t/2" target="_blank">ok2</a> <a href="#sec">ok3</a> <a href="vscode://file/x">ok4</a></p>')
  $lnkOut = @(& $py -X utf8 $uiKb ui-check $uiLnk --widths 1366 2>&1 | Out-String) -split "`n"
  Expect "ui-check LINK: a relative link without data-dw and a web link without target=_blank fail; drawer, new-tab, anchor and app links pass ($(@($lnkOut -match 'CLIP link') -join ' / '))" (@($lnkOut -match 'CLIP link: .*\(bad1 -> runs/a\.html\)').Count -eq 2 -and @($lnkOut -match 'CLIP link: .*\(bad2 -> https://x\.test/mr/1\)').Count -eq 2 -and @($lnkOut -match 'CLIP link').Count -eq 4)
  $uiTile = Join-Path (Kd) 'tile-classes.html'   # like tiles of unequal height: a finding; a short tile beside a tall one of another class: none; an svg over the tile below
  [IO.File]::WriteAllText($uiTile, '<div style="display:grid;grid-template-columns:repeat(3,1fr);align-items:start"><article class="t" style="height:40px">a</article><article class="t" style="height:200px">b</article><article class="t" style="height:40px">c</article></div><div style="display:grid;grid-template-columns:1fr 1fr;align-items:start"><article class="u" style="height:40px">d</article><article class="v" style="height:200px">e</article></div><div style="display:flex;flex-direction:column;width:300px"><div class="tg" style="height:50px">f<svg viewBox="0 0 100 100" style="display:block;width:100%;height:auto"></svg></div><div class="tb">g</div></div><div style="display:flex"><div class="tc" style="width:100px;height:60px;overflow:hidden"><svg width="300" height="300"></svg></div><div>h</div></div>')
  $uiTileOut = @(& $py -X utf8 $uiKb ui-check $uiTile --widths 1366 2>&1 | Out-String) -split "`n"
  Expect "ui-check: row heights compared within one tile class only; an svg over a sibling tile fails, one its tile clips passes ($(@($uiTileOut -match 'CLIP').Count))" (@($uiTileOut -match 'CLIP rows: card heights in one row differ by 160 px').Count -eq 2 -and @($uiTileOut -match 'CLIP rows: card heights').Count -eq 2 -and @($uiTileOut -match 'CLIP svg: ').Count -eq 2 -and @($uiTileOut -match 'CLIP svg: svg 300x\d+ px in one tile draws over a sibling tile .*\(tg x tb\)').Count -eq 2)
}
Remove-TestKit $k
Complete-Tests
